		{% set local_rights = "http://rightsstatements.org/vocab/InC-RUU/1.0/" %} 
	{% endif %}
	{% if data.rights_statements in ['No Copyright - Contractual Restrictions'] %} 
		{% set local_rights = "http://rightsstatements.org/vocab/NoC-CR/1.0/" %} 
	{% endif %} 
